      4:{sds:-3.2,ef_op:18.9,cmv:4.5,ticket:105,merma:3.4,quiebres:2,mo:97,kaizen:65,s1:65,s2:65,s3:70,s4:45,s5:30,kanban:55,venta_sug:60},
