// ── TABLA COMPARATIVA ──────────────────────────────────────────────────────
function TablaComp({fcs,semana,meta,getCurrent}){
  const kpis=[
    {k:"sds",     l:"SDS",         f:fmt1, cFn:(v)=>{ const m={sds_min:meta.sds_min,sds_max:meta.sds_max}; return sdsCol(v,m); }},
    {k:"ef_op",   l:"Ef. Op.",     f:fmt1, cFn:(v)=>kpiCol(v,meta.ef_op,false)},
    {k:"cmv",     l:"CMV %",       f:fmt1, cFn:(v)=>kpiCol(v,meta.cmv,true)},
    {k:"ticket",  l:"Ticket idx",  f:fmt1, cFn:(v)=>kpiCol(v,100+meta.ticket_delta,false)},
    {k:"merma",   l:"Merma %",     f:fmt1, cFn:(v)=>kpiCol(v,meta.merma,true)},
    {k:"quiebres",l:"Quiebres",    f:fmt0, cFn:(v)=>kpiCol(v,meta.quiebres,true)},
    {k:"kaizen",  l:"Kaizen %",    f:fmt0, cFn:(v)=>leanCol(v)},
  ];
  return(
    <div style={{overflowX:"auto"}}>
      <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
        <thead>
          <tr style={{background:"#f0f4f8"}}>
            <th style={TH}>KPI</th>
            {fcs.map((fc,i)=><th key={i} style={{...TH,color:fc.color}}>{fc.nombre}</th>)}
          </tr>
        </thead>
        <tbody>
          {kpis.map((row,ri)=>(
            <tr key={ri} style={{borderBottom:"1px solid #f0f0f0",
              background:ri%2===0?"#fff":"#fafafa"}}>
              <td style={{padding:"7px 10px",fontWeight:600,color:"#555"}}>{row.l}</td>
              {fcs.map((fc,i)=>{
                const cur=getCurrent(fc,semana);
                const v=cur?cur[row.k]:null;
                return(
                  <td key={i} style={{padding:"7px 10px",textAlign:"center"}}>
                    <span style={{fontWeight:700,color:v!=null?row.cFn(v):"#aaa"}}>{row.f(v)}</span>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// ── TABLA KPIs CON EDITAR / ELIMINAR ──────────────────────────────────────
function TablaKPIs({rows,meta,onEdit,onDel}){
  if(!rows.length) return <div style={{color:"#aaa",padding:12,fontSize:12}}>Sin datos cargados.</div>;
  const cols=["semana","sds","ef_op","cmv","ticket","merma","quiebres","mo","kaizen"];
  const lbl={semana:"Sem",sds:"SDS",ef_op:"Ef.Op",cmv:"CMV%",ticket:"Ticket",
    merma:"Merma%",quiebres:"Qbr",mo:"MO idx",kaizen:"Kaizen%"};
  return(
    <div style={{overflowX:"auto",maxHeight:280,overflowY:"auto"}}>
      <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
        <thead style={{position:"sticky",top:0,background:"#f0f4f8"}}>
          <tr>
            {cols.map(c=><th key={c} style={{...TH,fontSize:9,padding:"6px 8px"}}>{lbl[c]}</th>)}
            <th style={{...TH,fontSize:9,padding:"6px 8px"}}>Ops</th>
          </tr>
        </thead>
        <tbody>
          {[...rows].reverse().map((r,ri)=>(
            <tr key={ri} style={{borderBottom:"1px solid #f0f0f0",
              background:ri%2===0?"#fff":"#fafafa"}}>
              {cols.map(c=>{
                const v=r[c];
                let color="#333";
                if(c==="sds") color=sdsCol(v,meta);
                if(c==="ef_op") color=kpiCol(v,meta.ef_op,false);
                if(c==="cmv") color=kpiCol(v,meta.cmv,true);
                if(c==="merma") color=kpiCol(v,meta.merma,true);
                if(c==="quiebres") color=kpiCol(v,meta.quiebres,true);
                return(
                  <td key={c} style={{padding:"5px 8px",textAlign:"center",
                    fontWeight:c==="semana"?700:400,
                    color:c==="semana"?NAVY:color}}>
                    {c==="semana"?semLabel(v):(v==null?"—":["quiebres"].includes(c)?fmt0(v):fmt1(v))}
                  </td>
                );
              })}
              <td style={{padding:"5px 8px",textAlign:"center"}}>
                <div style={{display:"flex",gap:3,justifyContent:"center"}}>
                  <Btn tiny color={AMB} onClick={()=>onEdit(r.semana)}>✏</Btn>
                  <Btn tiny color={RED} onClick={()=>onDel(r.semana)}>✕</Btn>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// ── TABLA EDITABLE DATOS CARGADOS (Carga de Datos) ─────────────────────────
function TablaKPIsEdit({datos,meta,onEdit,onDel}){
  const semanas=Object.keys(datos).map(Number).sort((a,b)=>a-b);
  if(!semanas.length) return <div style={{color:"#aaa",fontSize:12}}>Sin datos cargados.</div>;
  const cols=["sds","ef_op","cmv","ticket","merma","quiebres","mo","kaizen"];
  const lbl={sds:"SDS",ef_op:"Ef.Op",cmv:"CMV%",ticket:"Ticket",
    merma:"Merma%",quiebres:"Qbr",mo:"MO idx",kaizen:"Kaizen%"};
  return(
    <div style={{overflowX:"auto"}}>
      <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
        <thead style={{background:"#f0f4f8"}}>
          <tr>
            <th style={{...TH,fontSize:9}}>Sem</th>
            {cols.map(c=><th key={c} style={{...TH,fontSize:9}}>{lbl[c]}</th>)}
            <th style={{...TH,fontSize:9}}>Ops</th>
          </tr>
        </thead>
        <tbody>
          {semanas.map((s,ri)=>{
            const d=datos[s];
            return(
              <tr key={s} style={{borderBottom:"1px solid #eee",
                background:ri%2===0?"#fff":"#fafafa"}}>
                <td style={{padding:"6px 8px",fontWeight:700,color:NAVY,textAlign:"center"}}>{semLabel(s)}</td>
                {cols.map(c=>{
                  const v=d[c];
                  let color="#333";
                  if(c==="sds") color=sdsCol(v,meta);
                  if(c==="ef_op") color=kpiCol(v,meta.ef_op,false);
                  if(c==="cmv") color=kpiCol(v,meta.cmv,true);
                  if(c==="merma") color=kpiCol(v,meta.merma,true);
                  if(c==="quiebres") color=kpiCol(v,meta.quiebres,true);
                  return(
                    <td key={c} style={{padding:"6px 8px",textAlign:"center",color}}>
                      {v==null?"—":["quiebres"].includes(c)?fmt0(v):fmt1(v)}
                    </td>
                  );
                })}
                <td style={{padding:"6px 8px",textAlign:"center"}}>
                  <div style={{display:"flex",gap:3,justifyContent:"center"}}>
                    <Btn tiny color={AMB} onClick={()=>onEdit(s)}>✏</Btn>
                    <Btn tiny color={RED} onClick={()=>onDel(s)}>✕</Btn>
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}


