// ── CELDA EDITABLE ─────────────────────────────────────────────────────────
function EditCell({value,onChange,placeholder="",disabled=false,type="text",style={}}){
  return(
    <input type={type} value={value} placeholder={placeholder} disabled={disabled}
      onChange={e=>onChange(e.target.value)}
      style={{border:disabled?"1px solid #eee":"1px solid #d0d0d0",
        borderRadius:3,padding:"4px 6px",fontSize:11,width:"100%",
        boxSizing:"border-box",background:disabled?"#f5f5f5":"#fff",
        color:disabled?"#bbb":"#333",...style}}/>
  );
}

// ── ISHIKAWA TABLE ─────────────────────────────────────────────────────────
function IshikawaTable({rows,setRows,nextId,setNextId,expanded,setExpanded,
  setPlanRows,setNextPlanId,nextPlanId,showToast}){

  const COLS=[
    {k:"pond",        label:"Ponderación %", w:80,  type:"number"},
    {k:"colaboradores",label:"Colaboradores",w:130},
    {k:"metodos",     label:"Métodos",       w:120},
    {k:"mediciones",  label:"Mediciones",    w:120},
    {k:"ambiente",    label:"Ambiente",      w:110},
    {k:"material",    label:"Material",      w:110},
    {k:"maquinas",    label:"Máquinas",      w:110},
    {k:"problema",    label:"Problema",      w:150},
  ];

  const totalPond=rows.reduce((s,r)=>s+(parseFloat(r.pond)||0),0);
  const pondOk=Math.abs(totalPond-100)<0.01;
  const pondOver=totalPond>100;

  const addRow=()=>{
    setRows(p=>[...p,{id:nextId,pond:"",colaboradores:"",metodos:"",
      mediciones:"",ambiente:"",material:"",maquinas:"",problema:"",
      porques:{q1:"",q2:"",q3:"",q4:"",q5:""}}]);
    setNextId(n=>n+1);
  };

  const delRow=(id)=>setRows(p=>p.filter(r=>r.id!==id));

  const updCell=(id,k,v)=>setRows(p=>p.map(r=>r.id===id?{...r,[k]:v}:r));
  const updQ=(id,qk,v)=>setRows(p=>p.map(r=>r.id===id?
    {...r,porques:{...r.porques,[qk]:v}}:r));

  const toggleExpand=(id)=>setExpanded(p=>({...p,[id]:!p[id]}));

  // Send root cause to Plan
  const sendToPlan=(row)=>{
    const pq=row.porques;
    // Find last filled Why
    let causa="";
    for(const k of["q5","q4","q3","q2","q1"]){
      if(pq[k]&&pq[k].trim()){causa=pq[k].trim();break;}
    }
    if(!causa){showToast("Completá al menos el Por Qué 1 antes de enviar",false);return;}
    const label=`[5PQ] ${row.problema||"Problema"} → Causa raíz: ${causa}`;
    setPlanRows(prev=>{
      // Avoid duplicate
      if(prev.some(p=>p.accion===label)) {
        showToast("Esta causa raíz ya está en el Plan",false);return prev;
      }
      const newId=nextPlanId;
      setNextPlanId(n=>n+1);
      return[...prev,{id:newId,accion:label,fechaIni:"",fechaFin:"",
        responsable:"",resultadoEsp:"",resultadoReal:"",avance:"",fuente:"porques"}];
    });
    showToast("✓ Causa raíz enviada al Plan de Acción");
  };

  return(
    <div>
      {/* Tabla principal */}
      <div style={{overflowX:"auto",marginBottom:10}}>
        <table style={{borderCollapse:"collapse",fontSize:11,width:"100%",minWidth:900}}>
          <thead>
            <tr style={{background:NAVY,color:"#fff"}}>
              <th style={{padding:"7px 6px",width:36}}/>
              {COLS.map(c=>(
                <th key={c.k} style={{padding:"7px 6px",width:c.w,
                  fontWeight:700,fontSize:10,textAlign:"left",whiteSpace:"nowrap"}}>
                  {c.label}
                </th>
              ))}
              <th style={{padding:"7px 6px",width:60,fontSize:10}}>Ops</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row,ri)=>(
              <>
                <tr key={row.id} style={{background:ri%2===0?"#fff":"#fafafa",
                  borderBottom:"1px solid #eee"}}>
                  {/* Expand button */}
                  <td style={{padding:"4px 6px",textAlign:"center"}}>
                    <button onClick={()=>toggleExpand(row.id)} style={{
                      background:"none",border:"none",cursor:"pointer",
                      fontSize:14,color:NAVY,padding:0,lineHeight:1}}>
                      {expanded[row.id]?"▾":"▸"}
                    </button>
                  </td>
                  {COLS.map(c=>(
                    <td key={c.k} style={{padding:"4px 6px"}}>
                      <EditCell value={row[c.k]} type={c.type||"text"}
                        onChange={v=>updCell(row.id,c.k,v)}
                        style={c.k==="pond"&&pondOver?{borderColor:RED}:{}}/>
                    </td>
                  ))}
                  <td style={{padding:"4px 6px",textAlign:"center"}}>
                    <div style={{display:"flex",gap:3,justifyContent:"center"}}>
                      <button onClick={()=>sendToPlan(row)} title="Enviar causa raíz al Plan"
                        style={{background:GRN,color:"#fff",border:"none",
                          borderRadius:3,padding:"3px 6px",fontSize:10,cursor:"pointer",
                          fontWeight:700}}>→Plan</button>
                      <button onClick={()=>delRow(row.id)}
                        style={{background:RED,color:"#fff",border:"none",
                          borderRadius:3,padding:"3px 7px",fontSize:11,cursor:"pointer"}}>✕</button>
                    </div>
                  </td>
                </tr>

                {/* 5 Por Qué expandible */}
                {expanded[row.id]&&(
                  <tr key={`pq-${row.id}`}>
                    <td colSpan={COLS.length+2} style={{padding:"0 0 0 36px",background:"#f0f4ff"}}>
                      <div style={{padding:"10px 14px"}}>
                        <div style={{fontWeight:700,fontSize:11,color:MID,marginBottom:8}}>
                          🔍 5 Por Qué — Problema: <span style={{color:NAVY}}>{row.problema||"(sin definir)"}</span>
                          <span style={{fontSize:10,color:"#888",marginLeft:8,fontWeight:400}}>
                            Completá secuencialmente. Cada respuesta es el disparador del siguiente.
                          </span>
                        </div>
                        <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:8}}>
                          {[
                            {k:"q1",label:"Por Qué 1",prev:null},
                            {k:"q2",label:"Por Qué 2",prev:"q1"},
                            {k:"q3",label:"Por Qué 3",prev:"q2"},
                            {k:"q4",label:"Por Qué 4",prev:"q3"},
                            {k:"q5",label:"Por Qué 5",prev:"q4"},
                          ].map((qDef,qi)=>{
                            const isLocked=qDef.prev&&!row.porques[qDef.prev]?.trim();
                            const isLast=qi===4;
                            const isRoot=isLast&&row.porques[qDef.k]?.trim();
                            return(
                              <div key={qDef.k} style={{position:"relative"}}>
                                <div style={{fontSize:10,fontWeight:700,
                                  color:isLocked?"#bbb":isRoot?GRN:MID,marginBottom:4}}>
                                  {isRoot?"🎯 CAUSA RAÍZ":qDef.label}
                                  {qi>0&&<span style={{color:"#aaa",fontWeight:400,marginLeft:4}}>
                                    ← {["q1","q2","q3","q4"][qi-1]}
                                  </span>}
                                </div>
                                <textarea
                                  value={row.porques[qDef.k]}
                                  disabled={isLocked}
                                  onChange={e=>updQ(row.id,qDef.k,e.target.value)}
                                  placeholder={isLocked?"Completá el anterior primero…":"¿Por qué?"}
                                  style={{width:"100%",height:80,
                                    border:`1px solid ${isRoot?GRN:isLocked?"#eee":"#ccc"}`,
                                    borderRadius:4,padding:"6px 8px",fontSize:11,
                                    boxSizing:"border-box",resize:"vertical",
                                    background:isLocked?"#f8f8f8":isRoot?"#f0fff4":"#fff",
                                    color:isLocked?"#ccc":"#333",fontFamily:"Arial,sans-serif"}}/>
                                {isLocked&&(
                                  <div style={{position:"absolute",top:24,left:0,right:0,
                                    bottom:0,cursor:"not-allowed",borderRadius:4}}/>
                                )}
                              </div>
                            );
                          })}
                        </div>
                        <div style={{marginTop:8,textAlign:"right"}}>
                          <button onClick={()=>sendToPlan(row)} style={{
                            background:GRN,color:"#fff",border:"none",
                            borderRadius:4,padding:"6px 16px",
                            fontSize:11,cursor:"pointer",fontWeight:700}}>
                            ✓ Enviar causa raíz al Plan →
                          </button>
                        </div>
                      </div>
                    </td>
                  </tr>
                )}
              </>
            ))}
          </tbody>
          {/* Totalizador ponderación */}
          <tfoot>
            <tr style={{background:pondOk?"#e8f5e9":pondOver?"#fdecea":"#fff8e1"}}>
              <td colSpan={2} style={{padding:"7px 10px",fontWeight:700,fontSize:12,
                color:pondOk?GRN:pondOver?RED:AMB,textAlign:"right"}}>
                TOTAL PONDERACIÓN:
              </td>
              <td style={{padding:"7px 10px",fontWeight:800,fontSize:14,
                color:pondOk?GRN:pondOver?RED:AMB}}>
                {totalPond.toFixed(1)}%
              </td>
              <td colSpan={COLS.length-1} style={{padding:"7px 10px",fontSize:11,
                color:pondOk?GRN:pondOver?RED:AMB}}>
                {pondOk?"✓ Ponderación correcta"
                  :pondOver?"✗ Error: sobrecarga — superás el 100%"
                  :`⚠ Falta agregar ponderación (faltan ${(100-totalPond).toFixed(1)}%)`}
              </td>
            </tr>
          </tfoot>
        </table>
      </div>
      <button onClick={addRow} style={{background:NAVY,color:"#fff",border:"none",
        borderRadius:5,padding:"7px 18px",fontSize:12,cursor:"pointer",fontWeight:700}}>
        + Agregar fila
      </button>
    </div>
  );
}

// ── MMM TABLE ──────────────────────────────────────────────────────────────
function MMMTable({rows,setRows,nextId,setNextId,setPlanRows,setNextPlanId,nextPlanId,showToast}){
  const COLS=[
    {k:"recurso",label:"Recurso",        w:180},
    {k:"muda",   label:"Muda (Desperdicio)",w:220},
    {k:"mura",   label:"Mura (Variabilidad)",w:220},
    {k:"muri",   label:"Muri (Sobrecarga)", w:220},
  ];

  const addRow=()=>{
    const newId=nextId;
    setNextId(n=>n+1);
    const newRow={id:newId,recurso:"",muda:"",mura:"",muri:""};
    setRows(p=>[...p,newRow]);
    // Auto-generate plan row
    const planLabel=`[MMM] Recurso #${newId} — completar descripción`;
    setPlanRows(prev=>{
      const planId=nextPlanId;
      setNextPlanId(n=>n+1);
      return[...prev,{id:planId,accion:planLabel,fechaIni:"",fechaFin:"",
        responsable:"",resultadoEsp:"",resultadoReal:"",avance:"",fuente:"mmm"}];
    });
  };

  const delRow=(id)=>setRows(p=>p.filter(r=>r.id!==id));
  const upd=(id,k,v)=>setRows(p=>p.map(r=>r.id===id?{...r,[k]:v}:r));

  return(
    <div>
      <div style={{overflowX:"auto",marginBottom:10}}>
        <table style={{borderCollapse:"collapse",fontSize:11,width:"100%"}}>
          <thead>
            <tr style={{background:MID,color:"#fff"}}>
              {COLS.map(c=>(
                <th key={c.k} style={{padding:"8px 10px",width:c.w,
                  textAlign:"left",fontWeight:700,fontSize:10}}>
                  {c.label}
                </th>
              ))}
              <th style={{padding:"8px 10px",width:50}}>Ops</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row,ri)=>(
              <tr key={row.id} style={{background:ri%2===0?"#fff":"#fafafa",
                borderBottom:"1px solid #eee"}}>
                {COLS.map(c=>(
                  <td key={c.k} style={{padding:"5px 8px"}}>
                    <EditCell value={row[c.k]} onChange={v=>upd(row.id,c.k,v)}
                      placeholder={c.k==="recurso"?"Ej: Freezer principal":""}/>
                  </td>
                ))}
                <td style={{padding:"5px 8px",textAlign:"center"}}>
                  <button onClick={()=>delRow(row.id)} style={{
                    background:RED,color:"#fff",border:"none",
                    borderRadius:3,padding:"3px 8px",fontSize:11,cursor:"pointer"}}>✕</button>
                </td>
              </tr>
            ))}
            {rows.length===0&&(
              <tr><td colSpan={5} style={{padding:20,textAlign:"center",color:"#aaa",fontSize:12}}>
                Sin registros. Agregá una fila.
              </td></tr>
            )}
          </tbody>
        </table>
      </div>
      <button onClick={addRow} style={{background:MID,color:"#fff",border:"none",
        borderRadius:5,padding:"7px 18px",fontSize:12,cursor:"pointer",fontWeight:700}}>
        + Agregar recurso → genera fila en Plan
      </button>
    </div>
  );
}

// ── PLAN TABLE ─────────────────────────────────────────────────────────────
function PlanTable({rows,setRows,nextId,setNextId}){
  const COLS=[
    {k:"accion",        label:"Plan de Acción",           w:220},
    {k:"fechaIni",      label:"Fecha Inicio",             w:100, type:"date"},
    {k:"fechaFin",      label:"Fecha Final",              w:100, type:"date"},
    {k:"responsable",   label:"Responsable",              w:130},
    {k:"resultadoEsp",  label:"Resultado a Alcanzar",     w:180},
    {k:"resultadoReal", label:"Resultado Realmente Alcanzado", w:180},
    {k:"avance",        label:"% Avance",                 w:80,  type:"number"},
  ];

  const FUENTE_BADGE={
    manual:   {bg:"#e8eef5",color:NAVY,   label:"Manual"},
    porques:  {bg:"#e8f5e9",color:GRN,    label:"5 Por Qué"},
    mmm:      {bg:"#fff3e0",color:AMB,    label:"MMM"},
  };

  const addRow=()=>{
    setRows(p=>[...p,{id:nextId,accion:"",fechaIni:"",fechaFin:"",
      responsable:"",resultadoEsp:"",resultadoReal:"",avance:"",fuente:"manual"}]);
    setNextId(n=>n+1);
  };
  const delRow=(id)=>setRows(p=>p.filter(r=>r.id!==id));
  const upd=(id,k,v)=>setRows(p=>p.map(r=>r.id===id?{...r,[k]:v}:r));

  // KPI de progreso
  const total=rows.length;
  const completas=rows.filter(r=>(parseFloat(r.avance)||0)>=98).length;
  const kpiPlan=total>0?Math.round((completas/total)*100):0;
  const kpiColor=kpiPlan>=80?GRN:kpiPlan>=50?AMB:RED;

  return(
    <div>
      {/* KPI global */}
      <div style={{background:"#f0f4f8",borderRadius:6,padding:"10px 16px",
        marginBottom:12,display:"flex",alignItems:"center",gap:20,
        border:`1px solid ${kpiColor}22`}}>
        <div>
          <div style={{fontSize:9,color:"#888",letterSpacing:1,textTransform:"uppercase"}}>
            PROGRESO DEL PLAN MAESTRO
          </div>
          <div style={{fontSize:32,fontWeight:800,color:kpiColor,lineHeight:1}}>
            {kpiPlan}%
          </div>
          <div style={{fontSize:10,color:"#666",marginTop:2}}>
            {completas} de {total} acciones completas (≥98%)
          </div>
        </div>
        <div style={{flex:1}}>
          <div style={{height:12,background:"#e0e0e0",borderRadius:6,overflow:"hidden"}}>
            <div style={{height:"100%",width:`${kpiPlan}%`,
              background:kpiColor,borderRadius:6,transition:"width .4s ease"}}/>
          </div>
          <div style={{fontSize:10,color:"#aaa",marginTop:4,display:"flex",gap:16}}>
            <span><span style={{color:GRN,fontWeight:700}}>■</span> Completa: avance ≥ 98%</span>
            <span><span style={{color:AMB,fontWeight:700}}>■</span> En curso: 50–97%</span>
            <span><span style={{color:RED,fontWeight:700}}>■</span> Pendiente: &lt;50%</span>
            <span style={{marginLeft:"auto"}}>
              Fórmula: (Acciones completas / Total acciones) × 100
            </span>
          </div>
        </div>
      </div>

      {/* Tabla */}
      <div style={{overflowX:"auto",marginBottom:10}}>
        <table style={{borderCollapse:"collapse",fontSize:11,width:"100%",minWidth:1100}}>
          <thead>
            <tr style={{background:NAVY,color:"#fff"}}>
              <th style={{padding:"7px 8px",width:60,fontSize:10}}>Origen</th>
              {COLS.map(c=>(
                <th key={c.k} style={{padding:"7px 8px",width:c.w,
                  textAlign:"left",fontWeight:700,fontSize:10,whiteSpace:"nowrap"}}>
                  {c.label}
                </th>
              ))}
              <th style={{padding:"7px 8px",width:60,fontSize:10}}>Estado</th>
              <th style={{padding:"7px 8px",width:40}}>Ops</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row,ri)=>{
              const avPct=parseFloat(row.avance)||0;
              const estado=avPct>=98?"Completa":avPct>=50?"En curso":"Pendiente";
              const estColor=avPct>=98?GRN:avPct>=50?AMB:RED;
              const badge=FUENTE_BADGE[row.fuente]||FUENTE_BADGE.manual;
              return(
                <tr key={row.id} style={{background:ri%2===0?"#fff":"#fafafa",
                  borderBottom:"1px solid #eee"}}>
                  <td style={{padding:"5px 8px",textAlign:"center"}}>
                    <span style={{background:badge.bg,color:badge.color,
                      padding:"2px 7px",borderRadius:10,fontSize:9,fontWeight:700,
                      whiteSpace:"nowrap"}}>
                      {badge.label}
                    </span>
                  </td>
                  {COLS.map(c=>(
                    <td key={c.k} style={{padding:"5px 6px"}}>
                      <EditCell value={row[c.k]||""} type={c.type||"text"}
                        onChange={v=>upd(row.id,c.k,v)}
                        style={c.k==="avance"?{
                          borderColor:estColor,
                          background:avPct>=98?"#f0fff4":avPct>=50?"#fffde7":"#fff"}:{}}/>
                    </td>
                  ))}
                  <td style={{padding:"5px 8px",textAlign:"center"}}>
                    <span style={{background:estColor+"22",color:estColor,
                      padding:"2px 8px",borderRadius:10,fontSize:9,fontWeight:700}}>
                      {estado}
                    </span>
                  </td>
                  <td style={{padding:"5px 6px",textAlign:"center"}}>
                    <button onClick={()=>delRow(row.id)} style={{
                      background:RED,color:"#fff",border:"none",
                      borderRadius:3,padding:"3px 8px",fontSize:11,cursor:"pointer"}}>✕</button>
                  </td>
                </tr>
              );
            })}
            {rows.length===0&&(
              <tr><td colSpan={COLS.length+3} style={{padding:24,textAlign:"center",
                color:"#aaa",fontSize:12}}>
                Sin acciones en el plan. Agregá una manualmente o enviá desde "5 Por Qué" o MMM.
              </td></tr>
            )}
          </tbody>
          {/* Totalizador */}
          <tfoot>
            <tr style={{background:kpiColor+"15",borderTop:`2px solid ${kpiColor}`}}>
              <td colSpan={2} style={{padding:"8px 12px",fontWeight:700,
                color:kpiColor,fontSize:12,textAlign:"right"}}>
                PROGRESO GLOBAL:
              </td>
              <td colSpan={COLS.length+1} style={{padding:"8px 12px",
                fontWeight:800,fontSize:16,color:kpiColor}}>
                {kpiPlan}% — {completas}/{total} acciones completas
              </td>
            </tr>
          </tfoot>
        </table>
      </div>
      <button onClick={addRow} style={{background:NAVY,color:"#fff",border:"none",
        borderRadius:5,padding:"7px 18px",fontSize:12,cursor:"pointer",fontWeight:700}}>
        + Agregar acción manual
      </button>
    </div>
  );
}
